(()=> {
  const defaults = { enabled: true, species: "dog", size: 3, off: [] };
  let memory = { ...defaults };
  const read = () => {
    try {
      return { ...memory, ...JSON.parse(localStorage.getItem("pixel-pet-settings") || "{}") };
    } catch {
      return memory;
    }
  };
  const write = (values) => {
    memory = { ...read(), ...values };
    try { localStorage.setItem("pixel-pet-settings", JSON.stringify(memory)); } catch {}
    return Promise.resolve();
  };
  const chromeApi = window.chrome || (window.chrome = {});
  chromeApi.storage = chromeApi.storage || {};
  chromeApi.storage.local = { get: (requested = {}) => Promise.resolve({ ...requested, ...read() }), set: write };
  chromeApi.storage.onChanged = chromeApi.storage.onChanged || { addListener() {} };
})();
